const int MAXN = 2e5 + 5;
typedef pair<int, int>pii;
int n;
pii arr[MAXN];
int main(){
	int t;
	cin >> t;
	while(t--){
		cin >> n;
		for(int i = 1; i <= n; i++){
			int num;
			cin >> num;
			arr[i] = {num, i};
		}
		sort(arr + 1, arr + n + 1);
		int minn = (int)1e9;
		int maxn = -1;
		int ans = 0;
		for(int i = 1; i <= n; i++){
			maxn = max(maxn, arr[i].second);
			minn = min(minn, arr[i].second);
			if(maxn - minn + 1 <= i)ans++;
		}
		cout << ans << endl;
	}
}
